#' @inheritParams calculate_heat_gdh
#' @return A numeric vector of length length(temp)-1. Element i is the potential
#' heat increment over interval i to i+1, using temp[i]. It is not cumulative.
#' @export
calculate_heat_gdh_unscaled <- function(temp, times, Tu = 25, Tb = 4, Tc = 36, deg_celsius = TRUE) {
    .Call('_evalpheno_calculate_heat_gdh_unscaled', PACKAGE = 'evalpheno', temp, times, Tu, Tb, Tc, deg_celsius)
}

